const crypto = require('crypto');
const items = $input.all();
const out = [];
for (const item of items) {
  const headers = item.json.headers || {};
  const raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body ?? item.json);
  const body = typeof item.json.body === 'object' && item.json.body ? item.json.body : JSON.parse(raw);
  const secret = $env.N8N_WEBHOOK_SECRET || $env.ASF_WEBHOOK_SECRET;
  const ts = headers['x-asf-timestamp'] || headers['X-Asf-Timestamp'];
  const sig = headers['x-asf-signature'] || headers['X-Asf-Signature'];
  if (!secret || !ts || !sig) throw new Error('Unauthorized: missing signature');
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${typeof item.json.body === 'string' ? item.json.body : JSON.stringify(body)}`).digest('hex');
  if (expected !== sig) throw new Error('Unauthorized: bad signature');
  const skew = Math.abs(Date.now() - Number(ts));
  if (skew > 5 * 60 * 1000) throw new Error('Unauthorized: timestamp skew');
  const staticData = $getWorkflowStaticData('global');
  staticData.seen = staticData.seen || {};
  const key = body.idempotency_key || body.event_id;
  if (staticData.seen[key]) {
    out.push({ json: { duplicate: true, event: body } });
    continue;
  }
  staticData.seen[key] = Date.now();
  out.push({ json: { duplicate: false, event: body } });
}
return out;

const status = $input.first().json;
if (!status.ok) throw new Error('ASF status fetch failed');
if (status.project.cancelled || status.project.paused) {
  return [{ json: { stop: true, reason: status.project.paused ? 'paused' : 'cancelled', status } }];
}
const scenes = status.scenes || [];
const next = scenes.find(s => !['REAL_GENERATED','READY_FOR_ASSEMBLY','COMPLETED'].includes(s.state) || s.asset_origin !== 'REAL_GENERATED');
if (!next) {
  return [{ json: { stop: false, all_verified: true, status } }];
}
return [{ json: { stop: false, all_verified: false, next_scene: next, status, event: $('Validate Signature + Idempotency').first().json.event } }];
